#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==3,"usage: dual_words OUT weight");fs::path o=argv[1];size_t mw=std::stoul(argv[2]);std::vector<std::vector<I>>words(1);std::vector<Q>scale(1,Q(1));for(size_t w=1;w<=mw;++w){auto t=read(o/("FEC_"+std::to_string(w)+".wxf"));auto b=flatten(t);t.clear();PrivateCarrierChart c(b);require(c.complete,"No complete row-private chart");std::vector<std::vector<I>>nw(b.nrow);std::vector<Q>ns(b.nrow);for(size_t i=0;i<b.nrow;++i){size_t p=c.columns[i]/88,j=c.columns[i]%88;nw[i]=words[p];nw[i].push_back(index(j+1));ns[i]=scale[p]*c.values[i];}words=std::move(nw);scale=std::move(ns);std::ofstream f(o/("dual_words_w"+std::to_string(w)+".json"));f<<"{\"weight\":"<<w<<",\"dimension\":"<<b.nrow<<",\"complete_row_private_chart\":true,\"alphabet\":\"dense retained88, one-based\",\"rows\":[";for(size_t i=0;i<words.size();++i){if(i)f<<',';f<<"{\"word\":[";for(size_t j=0;j<w;++j){if(j)f<<',';f<<words[i][j];}f<<"],\"diagonal_value\":\""<<scale[i]<<"\"}";}f<<"]}\n";std::cout<<"DUAL_WORDS weight="<<w<<" dimension="<<b.nrow<<" private_column_induction=pass\n";}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
